import { ApiProperty } from '@nestjs/swagger';
import {
  IsNotEmpty,
  IsOptional,
  IsString,
  Length,
  MaxLength,
} from 'class-validator';

export class PairDeviceDto {
  @ApiProperty({
    example: '7K9X2B',
    description:
      '6-character uppercase pairing code generated by restaurant manager',
  })
  @IsNotEmpty()
  @IsString()
  @Length(6, 6)
  code: string;

  @ApiProperty({
    example: 'Kitchen Display Tablet 1',
    description: 'Name or label for the physical device being paired',
  })
  @IsNotEmpty()
  @IsString()
  @MaxLength(100)
  deviceName: string;

  @ApiProperty({
    example: 'android-uuid-94821',
    description: 'Optional unique hardware identifier from tablet or POS',
    required: false,
  })
  @IsOptional()
  @IsString()
  @MaxLength(128)
  hardwareId?: string;
}
